INSERT INTO interpretation_templates (condition_key, condition_value, category, title, summary, content, weight, is_active) VALUES
('day_pillar', '갑신', 'general', '갑신일주 · 총운', '바위 위에 뿌리내린 늠름한 소나무처럼 결단력이 강하고 위엄이 넘치는 기질입니다.', '갑목의 뻗어나가는 기상과 신금의 날카로운 바위가 만나 금극목의 편관을 이루는 형태입니다. 겉보기에는 호탕하고 대범하지만 속으로는 끊임없는 자기 검열과 긴장감을 유지하며 원칙을 중요시합니다. 어려운 난관 앞에서도 물러서지 않고 돌파하려는 독립심과 카리스마가 돋보입니다.', 70, true),
('day_pillar', '갑신', 'career', '갑신일주 · 직업', '명예를 중시하며 권위와 카리스마를 발휘할 수 있는 군검경, 정치, 무역 분야에 적합합니다.', '역마의 기운과 편관의 결단력이 결합되어 조직을 강하게 통솔하거나 큰 무대에서 활약할 때 능력을 인정받습니다. 사람들의 존경을 받는 공직, 법조계 혹은 해외를 넘나들며 개척 정신을 발휘하는 유통이나 무역업에서 주도적인 리더십을 발휘하기 좋습니다.', 70, true),
('day_pillar', '갑신', 'love', '갑신일주 · 연애', '솔직하고 열정적인 연애를 선호하지만, 굽히지 않는 자존심으로 인해 충돌할 수 있습니다.', '마음에 드는 상대에게 거침없이 다가가고 관계를 확실하게 리드하는 성향을 띱니다. 상대를 보호하려는 책임감이 강하나 자신의 원칙을 고집하고 훈계하려는 태도가 마찰을 빚을 수 있으므로 상대의 감정을 섬세하게 헤아리고 져주는 미덕을 기르는 것이 필수적입니다.', 70, true),
('day_pillar', '갑신', 'wealth', '갑신일주 · 재물', '도전적인 목표와 명예를 좇는 과정에서 큰 규모의 재물을 운용하는 성향입니다.', '안정적인 소액 저축보다는 명예를 높이거나 권력을 쥐어 자연스럽게 수익을 창출하는 흐름에 유리합니다. 재물을 목표로 하기보다 가치 있는 프로젝트나 자신의 명망에 집중할 때 경제적 성취가 뒤따르며 투기성 사업보다는 안정적인 부동산 등에 투자하는 것이 바람직합니다.', 70, true),
('day_pillar', '갑신', 'health', '갑신일주 · 건강', '금기운이 목기운을 압박하므로 간이나 담, 뼈와 관절 건강에 유의하면 좋습니다.', '긴장 상태가 지속되어 어깨나 목 주변의 근육이 뭉치기 쉽고 피로가 간에 누적될 우려가 있습니다. 규칙적인 스트레칭으로 굳은 관절을 부드럽게 풀어주고, 심신의 이완을 돕는 정적인 휴식을 취하여 편관의 압박감을 덜어내는 생활 습관이 건강 관리에 중요합니다.', 70, true),
('day_pillar', '을유', 'general', '을유일주 · 총운', '바위 틈새에서 피어난 난초처럼 예리하고 섬세하며 굽히지 않는 생명력을 지녔습니다.', '부드러운 을목이 날카로운 유금 위에 앉아 있는 편관의 구조로, 겉은 여려 보이나 속은 매우 차갑고 예민한 외유내강의 기질을 지닙니다. 주변 상황을 꿰뚫어 보는 통찰력이 비상하며 미적 감각이 뛰어나고 맺고 끊음이 대단히 확실하여 선을 넘는 것을 용납하지 않습니다.', 70, true),
('day_pillar', '을유', 'career', '을유일주 · 직업', '예리한 관찰력과 정밀함을 요구하는 금융, 기획, 의료, 디자인 분야에 잘 맞습니다.', '날카로운 비판력과 완벽주의를 발휘할 수 있는 회계사, 세무사, 한의사 등 전문적인 기술을 다루는 직업에서 뛰어난 역량을 보입니다. 또한 뛰어난 감각을 활용하여 섬세함을 요하는 예술이나 디자인 영역에서도 남다른 결과물을 창출해 내는 편입니다.', 70, true),
('day_pillar', '을유', 'love', '을유일주 · 연애', '매력적인 외모로 호감을 끌지만 잣대가 엄격하여 신중하고 차갑게 관계를 맺습니다.', '도화의 기운으로 이성에게 인기가 많으나, 완벽을 추구하는 성격 탓에 연인에게도 높은 기준을 요구하기 쉽습니다. 상대방의 작은 실수에도 예민하게 반응하거나 날카로운 지적을 할 수 있으므로 너그럽게 포용하려는 노력이 관계의 안정성을 높여줍니다.', 70, true),
('day_pillar', '을유', 'wealth', '을유일주 · 재물', '치밀하고 냉정한 판단력으로 불필요한 지출을 통제하며 재산을 관리하는 성향입니다.', '돈을 허투루 쓰는 법이 없고 꼼꼼하게 실속을 챙기므로 재물의 손실이 적습니다. 크게 모험을 거는 사업보다는 자신의 날카로운 기술이나 자격을 바탕으로 착실하게 수익을 창출하는 것이 안전하며, 금전 관리에 있어 대단히 계산적이고 투명한 흐름을 유지합니다.', 70, true),
('day_pillar', '을유', 'health', '을유일주 · 건강', '금극목의 작용으로 간장 질환이나 신경성 두통, 관절염 등에 신경 쓰면 좋습니다.', '신경이 항상 곤두서 있어 스트레스성 편두통이나 불면증에 시달릴 수 있으니 정신적인 여유를 갖는 것이 우선입니다. 뼈와 인대가 약해질 수 있으므로 무리한 운동을 피하고 요가나 수영 등 관절에 무리가 가지 않는 운동으로 유연성을 기르는 것이 건강 유지에 이롭습니다.', 70, true),
('day_pillar', '병술', 'general', '병술일주 · 총운', '가을 들판을 비추는 황혼처럼 따뜻하고 열정적이면서도 고독을 품은 기질입니다.', '밝고 환한 병화가 건조하고 묵직한 술토를 만나 식신의 기운을 발산하는 형상입니다. 사람들에게 베풀기를 좋아하고 언변이 화려하며 다정다감하지만 화려함 뒤에는 알 수 없는 쓸쓸함과 예민함이 서려 있습니다. 한 번 화가 나면 불길이 치솟듯 욱하는 기질도 숨어 있습니다.', 70, true),
('day_pillar', '병술', 'career', '병술일주 · 직업', '뛰어난 언변과 기획력을 발휘할 수 있는 교육, 종교, 상담, 언론 분야에 적합합니다.', '사람의 마음을 움직이는 언어 능력이 출중하여 남을 가르치는 교육자나 상담가, 활인업 종사자로서 크게 성공할 수 있습니다. 지장간에 숨은 재성을 활용하여 전문적인 지식을 바탕으로 기획이나 마케팅 분야에서도 독립적인 역량을 뽐내며 좋은 성과를 냅니다.', 70, true),
('day_pillar', '병술', 'love', '병술일주 · 연애', '다정하고 매력적이지만 감정의 기복이 심해 외로움을 잘 타는 편입니다.', '불처럼 뜨겁고 화려하게 연애를 주도하며 연인에게 헌신하지만 깊은 내면의 고독감 탓에 사랑을 받으면서도 공허함을 느낄 수 있습니다. 백호살의 기운으로 인해 갈등이 생기면 자존심을 심하게 내세울 수 있으므로 상대방과 차분하게 감정을 나누는 소통이 필수적입니다.', 70, true),
('day_pillar', '병술', 'wealth', '병술일주 · 재물', '전문 지식을 바탕으로 재물을 축적하며 흙 속에 재산을 감춰두는 성향을 가집니다.', '식신생재의 흐름으로 자신의 아이디어나 재능을 통해 끊임없이 수익을 창출해 냅니다. 돈을 잘 벌기도 하지만 술토라는 창고를 깔고 앉아 겉으로 드러나지 않게 재산을 묶어두는 능력이 탁월하여 부동산이나 저작권 등 문서화된 자산으로 관리할 때 든든한 부를 누립니다.', 70, true),
('day_pillar', '병술', 'health', '병술일주 · 건강', '화기가 강하고 건조하므로 심혈관계나 위장, 호흡기 건강 관리에 유의하면 좋습니다.', '수분이 부족해지기 쉬운 체질로 위장에 열이 뭉쳐 소화 장애나 변비가 발생할 수 있습니다. 맵고 자극적인 음식을 피하고 수분을 충분히 보충해 주는 것이 좋으며, 감정의 기복으로 심장에 무리가 가지 않도록 명상 등으로 평온함을 유지하는 것이 바람직합니다.', 70, true),
('day_pillar', '정해', 'general', '정해일주 · 총운', '호수 위를 비추는 달빛처럼 영감이 뛰어나고 섬세하며 신비로운 분위기를 자아냅니다.', '따뜻한 정화가 차가운 해수 위에 떠 있는 구조로, 정관의 바른 성품과 함께 비상한 두뇌와 직관력을 지녔습니다. 예의 바르고 온화하여 타인에게 부드럽게 다가가지만, 속마음을 쉽게 드러내지 않고 사색과 철학적인 사유에 깊이 빠져드는 예민한 내면을 가졌습니다.', 70, true),
('day_pillar', '정해', 'career', '정해일주 · 직업', '통찰력과 안정성을 요하는 공직, 교육, 심리학, 활인업 및 정보통신 분야에 잘 맞습니다.', '천문성의 영향으로 영감과 통찰력이 뛰어나 상담사, 정신과 의사, 종교인 등 사람의 내면을 다루는 직업에서 남다른 두각을 나타냅니다. 규칙적이고 체계적인 조직 생활에도 무난히 적응하며 뛰어난 아이디어를 바탕으로 기획이나 학문적 연구에서도 훌륭한 성취를 냅니다.', 70, true),
('day_pillar', '정해', 'love', '정해일주 · 연애', '부드럽고 낭만적이며 상대방을 배려하지만, 의심과 불안감을 내면에 품기 쉽습니다.', '정 많고 세심한 성격으로 연애를 안정적으로 이끌어가나 상상력이 풍부해 일어나지 않은 일에 대해 지레 걱정하거나 의심할 수 있습니다. 상대에게 헌신하는 만큼 자신도 사랑받고 확인받기를 원하므로 서로에게 깊은 신뢰와 안정감을 주는 따뜻한 대화가 몹시 중요합니다.', 70, true),
('day_pillar', '정해', 'wealth', '정해일주 · 재물', '위험한 투자보다는 명예와 직위를 통해 안정적인 재물을 차곡차곡 쌓는 흐름입니다.', '관성 속에 재성을 품어 조직 내에서 인정을 받으며 그에 비례하여 경제적인 안정을 누리는 구조에 강합니다. 투기적인 욕심을 부리기보다는 자신의 지적 재산이나 자격증, 안정적인 직장을 바탕으로 성실하게 자산을 관리하는 것이 경제적 풍요를 지키는 길입니다.', 70, true),
('day_pillar', '정해', 'health', '정해일주 · 건강', '수와 화의 대비로 심장이나 시력, 비뇨기 계통의 건강 관리에 신경 쓰면 좋습니다.', '정신적인 스트레스를 많이 받는 편이므로 신경성 두통이나 불면증에 취약할 수 있습니다. 시력이 떨어지거나 심혈관에 무리가 갈 수 있으니 과도한 사색을 줄이고 가벼운 산책과 체온을 덥혀주는 식습관을 통해 신체의 기혈 순환을 돕는 것이 장기적으로 유익합니다.', 70, true),
('day_pillar', '무자', 'general', '무자일주 · 총운', '거대한 겨울 산처럼 듬직하고 과묵하며, 내면에 뛰어난 실속과 지혜를 감춘 기질입니다.', '무토의 포용력과 자수의 냉철한 이성이 결합되어 겉으로는 무뚝뚝해 보여도 대단히 계산이 빠르고 이성적입니다. 감정을 겉으로 잘 드러내지 않으나 정재의 영향으로 매사에 꼼꼼하고 현실적이며 치밀한 계획성을 바탕으로 손해 보는 일을 하지 않는 신중한 성향을 보입니다.', 70, true),
('day_pillar', '무자', 'career', '무자일주 · 직업', '계산이 정확하고 꼼꼼함을 요하는 재무, 회계, 부동산, 금융 분야에 훌륭하게 맞습니다.', '물질적인 실리를 추구하는 성향이 강해 은행원, 세무사 등 돈을 다루는 직종에서 능률을 발휘하기 좋습니다. 또한 흙 속에 물을 담아두듯 정보나 재물을 모으는 능력이 탁월하므로 부동산 관련 비즈니스나 자산을 관리하는 업무에서 신뢰를 얻고 두각을 나타냅니다.', 70, true),
('day_pillar', '무자', 'love', '무자일주 · 연애', '표현은 서툴러도 책임감 있고 다정하며, 현실적이고 안정적인 관계를 추구합니다.', '무뚝뚝한 겉모습 때문에 무심해 보일 수 있으나 내면에는 상대를 알뜰하게 챙기는 다정함이 숨어 있습니다. 화려하고 불타는 연애보다는 생활력이 강하고 안정감을 주는 관계를 선호하며, 갈등 시 다소 꽁한 모습을 보일 수 있으므로 부드럽고 솔직한 감정 표현이 요구됩니다.', 70, true),
('day_pillar', '무자', 'wealth', '무자일주 · 재물', '탁월한 경제 관념을 바탕으로 근검절약하여 알짜배기 재산을 든든히 축적하는 성향입니다.', '허영심을 부리지 않고 대단히 실속 있게 자산을 굴려 남몰래 튼튼한 경제적 기반을 마련합니다. 위험한 횡재수보다는 자신의 땀방울과 철저한 저축으로 부를 일구는 데 강하며 흙이 물을 흡수하듯 한 번 들어온 돈은 쉽게 내어주지 않아 알부자로 거듭날 잠재력이 충분합니다.', 70, true),
('day_pillar', '무자', 'health', '무자일주 · 건강', '냉기가 뭉쳐 발생할 수 있는 신장, 방광 질환 및 소화기 계통 관리에 유의하면 좋습니다.', '건조하고 차가운 기운이 맞물려 하복부가 냉해지거나 생식기 질환에 취약할 수 있으니 항상 몸을 따뜻하게 유지하는 것이 이롭습니다. 위장 기능이 둔화될 우려가 있으므로 규칙적인 유산소 운동을 통해 혈액순환을 촉진하고 땀을 배출하는 습관이 건강을 유지하는 비결입니다.', 70, true),
('day_pillar', '기축', 'general', '기축일주 · 총운', '얼어붙은 논밭처럼 끈질긴 인내력과 뚝심으로 한 우물을 파는 묵직한 기질입니다.', '기토의 유연함과 축토의 끈기가 만나 비견을 이루며 대단한 고집과 주관을 자랑합니다. 남의 말에 쉽게 흔들리지 않고 묵묵히 자신의 길을 개척하며 겉보기에는 수더분하지만 속에는 굽히지 않는 오기가 숨어 있습니다. 시련 속에서도 묵묵히 이겨내는 대기만성형의 표본입니다.', 70, true),
('day_pillar', '기축', 'career', '기축일주 · 직업', '강한 지구력과 특수성을 요하는 종교, 전문 기술, 부동산, 연구 분야에 적합합니다.', '쉽게 포기하지 않고 한 분야에 깊이 몰두하는 장인 정신이 있어 연구원이나 장인, 종교인, 철학자로서 큰 성과를 이룰 수 있습니다. 땅과 인연이 깊어 건축이나 부동산 분야에서도 능력을 발휘하며 조직의 리더보다는 독자적으로 역량을 펼치는 특수 직무에서 유리합니다.', 70, true),
('day_pillar', '기축', 'love', '기축일주 · 연애', '신중하게 곁을 내어주며, 무뚝뚝하지만 한 번 마음을 열면 변치 않는 의리를 보여줍니다.', '마음의 문을 여는 데 시간이 오래 걸리고 애정 표현에 서툴러 연인에게 답답함을 줄 수 있습니다. 로맨틱한 분위기보다는 상대방의 짐을 덜어주고 끝까지 책임지려는 든든함으로 사랑을 증명하므로 서로의 다름을 이해하고 부드러운 대화로 소통하려는 노력이 뒷받침되어야 합니다.', 70, true),
('day_pillar', '기축', 'wealth', '기축일주 · 재물', '근검절약이 몸에 배어 있으며 부동산이나 땅을 통해 묵직하게 자산을 불려 가는 성향입니다.', '투기성 자산보다는 흙의 기운을 살린 땅이나 건물 등 보이지 않는 든든한 자산에 묻어두어 경제적 부를 축적합니다. 돈을 다루는 데 극도로 신중하고 보수적이라 쉽게 재산을 잃지 않으며 중년 이후에 안정적으로 커다란 부를 누리게 되는 튼튼한 흐름을 가집니다.', 70, true),
('day_pillar', '기축', 'health', '기축일주 · 건강', '비위장이 약해지기 쉽고 몸이 찰 수 있으니 소화기 계통과 보온에 유의하면 좋습니다.', '차가운 흙의 기운이 겹쳐 소화 기능이 둔화되거나 위장병에 시달릴 수 있으므로 맵고 짠 음식을 피해야 합니다. 스트레스를 안으로 삭여 간과 위장에 열이 발생할 수 있으니 가벼운 등산이나 명상을 통해 속마음을 비워내고 신체를 따뜻하게 유지하는 것이 중요합니다.', 70, true),
('day_pillar', '경인', 'general', '경인일주 · 총운', '호랑이를 탄 장군처럼 용맹하고 독립심이 강하며 거침없이 돌진하는 기백입니다.', '경금의 단단한 무기가 인목의 생동감 넘치는 호랑이를 제어하는 편재의 구조로 명예욕과 승부욕이 대단합니다. 결단력이 뛰어나고 불의를 보면 참지 못하는 의협심이 있으며 새로운 환경에서도 주눅 들지 않고 역동적으로 일을 추진하는 강력한 카리스마를 발휘합니다.', 70, true),
('day_pillar', '경인', 'career', '경인일주 · 직업', '권력과 역마성을 동시에 쓰는 무역, 외교, 군검경, 대형 유통 및 사업 분야에 훌륭하게 맞습니다.', '큰 스케일과 활동력을 요구하는 글로벌 무역업이나 해운, 통신 분야에서 역동적으로 역량을 펼치기 좋습니다. 남의 밑에 있기보다 조직의 리더로서 주도권을 쥐거나 강력한 결단력이 필요한 권력 기관, 대형 프랜차이즈 사업 등에서 눈부신 성취를 이뤄내는 타입입니다.', 70, true),
('day_pillar', '경인', 'love', '경인일주 · 연애', '당당하고 열정적으로 리드하는 연애를 선호하지만, 자기중심적인 면이 강할 수 있습니다.', '마음에 드는 상대에게 주저 없이 호감을 표시하며 시원시원하고 통 큰 모습으로 매력을 발산합니다. 그러나 연애에 있어서도 통제하려는 성향이나 고집을 앞세우다 마찰을 빚을 수 있으므로 상대방의 의견을 융통성 있게 수용하고 다정하게 배려하는 태도가 꼭 필요합니다.', 70, true),
('day_pillar', '경인', 'wealth', '경인일주 · 재물', '작은 돈에 연연하지 않고 큰 사업적 승부나 활동력을 바탕으로 거대한 부를 일구는 성향입니다.', '재물의 스케일이 남달라 한 번에 굵직한 수익을 올리는 능력이 탁월하지만 돈이 크게 들어오고 크게 나가는 기복을 동반합니다. 유통업이나 해외 관련 사업으로 재물을 얻기 좋으며 굴린 현금을 즉시 부동산 등의 안전 자산으로 전환하는 지혜가 있어야 부를 지킬 수 있습니다.', 70, true),
('day_pillar', '경인', 'health', '경인일주 · 건강', '과로로 인한 신경계 무리 및 근골격계 질환, 간 기능 관리에 신경 쓰면 좋습니다.', '강한 활동력과 승부욕으로 체력을 과신하다가 간이나 뼈, 관절에 무리가 올 수 있으니 유의해야 합니다. 금극목의 영향으로 신경이 날카로워질 수 있으므로 충분한 수면을 취하고 스트레칭이나 근육 이완을 도와주는 활동을 병행하여 신체의 피로를 적극적으로 풀어야 합니다.', 70, true),
('day_pillar', '신묘', 'general', '신묘일주 · 총운', '예리한 칼날 앞의 화초처럼 섬세하고 눈치가 빠르며 예술적 감각이 돋보이는 기질입니다.', '신금의 날카로움이 묘목을 다듬는 편재의 구조로 두뇌 회전이 매우 비상하고 사람의 마음을 읽어내는 통찰력이 출중합니다. 겉보기엔 부드럽고 세련되었으나 속으로는 대단히 계산적이고 날카로워 손해 보는 일을 꺼리며 환경 적응력과 위기 대처 능력이 남다르게 뛰어납니다.', 70, true),
('day_pillar', '신묘', 'career', '신묘일주 · 직업', '정밀함과 손재주, 예리한 분석력을 요하는 디자인, 기획, 금융, 전문 기술 분야에 적합합니다.', '예술적 감각과 세밀한 계산 능력이 결합되어 인테리어, 패션 디자인, 미용 등 감각적인 분야에서 두각을 나타냅니다. 또한 숫자와 정보를 치밀하게 다루는 회계사, 세무사나 기획 업무에서도 자신만의 특출난 재능을 발휘하여 탁월한 전문성을 인정받기 쉽습니다.', 70, true),
('day_pillar', '신묘', 'love', '신묘일주 · 연애', '세련된 매력으로 호감을 사며 연인을 꼼꼼히 살피지만, 잣대가 높아 예민하게 반응합니다.', '매너 있고 눈치가 빨라 연애의 주도권을 잘 잡으며 다정하게 상대를 챙기나 속으로는 까다로운 기준을 적용합니다. 상대방의 단점이 눈에 띄면 날카롭게 지적하거나 차갑게 돌아서는 성향이 있으므로 서로의 부족함을 감싸안는 너그러운 포용력을 기르는 것이 바람직합니다.', 70, true),
('day_pillar', '신묘', 'wealth', '신묘일주 · 재물', '빠른 눈치와 계산 능력을 바탕으로 치밀하게 실속을 챙기며 재물을 관리하는 흐름입니다.', '재물의 흐름을 파악하는 감각이 탁월하여 헛돈을 쓰지 않고 꼼꼼하게 자산을 굴리는 알짜배기 성향을 지녔습니다. 타인과 복잡하게 얽히는 동업보다는 뛰어난 전문 지식이나 예리한 기술을 독자적으로 발휘할 때 경제적 보상이 안정적이고 풍성하게 따르는 구조입니다.', 70, true),
('day_pillar', '신묘', 'health', '신묘일주 · 건강', '금극목의 영향으로 신경이 예민해지고 간이나 관절 건강이 약해질 수 있으니 유의하면 좋습니다.', '긴장 상태가 잦아 편두통이나 신경성 위염에 시달릴 수 있으니 심리적인 압박감을 풀어주는 명상이나 휴식이 필수적입니다. 신경이 날카로워지면 시력이 떨어지거나 손목, 발목 등 관절 부위에 무리가 올 수 있으므로 부드러운 스트레칭으로 긴장을 완화시키는 것이 이롭습니다.', 70, true),
('day_pillar', '임진', 'general', '임진일주 · 총운', '거대한 댐 속에 갇힌 강물처럼 배포가 크고 권력욕이 강하며 속을 알 수 없는 기질입니다.', '임수의 깊은 물이 진토라는 거대한 흙의 댐에 모인 편관 괴강살의 형태로 카리스마와 리더십이 대단합니다. 겉보기엔 부드럽고 스케일이 커 보이지만 내면에는 남에게 굽히기 싫어하는 극강의 자존심과 승부욕을 품고 있으며 한번 결단하면 끝장을 보는 돌파력을 보여줍니다.', 70, true),
('day_pillar', '임진', 'career', '임진일주 · 직업', '생살여탈권을 쥐거나 거대한 스케일의 군검경, 정치, 토목, 대형 사업 분야에 맞습니다.', '조직의 말단에서 순응하기보다는 권력을 다루고 통솔력을 발휘할 수 있는 수사기관, 법조계 혹은 거대한 자금이 오가는 건축, 부동산 개발에서 크게 성공합니다. 위기 상황에서 진가를 발휘하는 결단력이 있어 큰 무대에서 활약하는 리더나 사업가로 적합합니다.', 70, true),
('day_pillar', '임진', 'love', '임진일주 · 연애', '책임감이 대단히 강하고 배우자를 든든히 지키려 하나 고집으로 인해 마찰이 잦을 수 있습니다.', '가벼운 만남을 싫어하고 진지하게 연애에 임하며 내 사람이라 여기면 물심양면으로 보호하는 듬직함을 갖췄습니다. 하지만 자기주장이 워낙 강하고 지배하려는 성향이 표출되면 상대가 억압감을 느낄 수 있으므로 부드러운 양보와 감정적인 교류를 의식적으로 실천해야 합니다.', 70, true),
('day_pillar', '임진', 'wealth', '임진일주 · 재물', '일확천금의 배포를 가졌으며 큰 기복 속에서도 막대한 부와 명예를 거머쥐는 대부호의 성향입니다.', '푼돈보다는 굵직한 프로젝트나 부동산, 투자를 통해 거대한 자산을 운용하는 스케일을 자랑합니다. 위기를 기회로 바꾸는 기개가 돋보여 한 번 흐름을 타면 크게 성공하지만 무리한 확장 탓에 손실을 볼 수도 있으니 돈을 땅이나 문서로 단단하게 묶어두는 지혜가 필요합니다.', 70, true),
('day_pillar', '임진', 'health', '임진일주 · 건강', '과도한 활동으로 인한 위장 및 신장 질환, 혈압 문제에 유의하고 스트레스를 관리하면 좋습니다.', '에너지를 한 번에 쏟아붓는 성향 탓에 소화 기능이 떨어지거나 비뇨기 계통에 무리가 올 수 있는 체질입니다. 과로나 폭음을 자제하고 규칙적인 유산소 운동으로 수분 대사를 원활하게 하며 긴장을 이완시키는 명상이나 요가를 생활화하는 것이 장기적인 건강에 큰 도움이 됩니다.', 70, true),
('day_pillar', '계사', 'general', '계사일주 · 총운', '아지랑이 피어나는 맑은 이슬처럼 지혜롭고 수완이 뛰어나며 변화에 민첩한 기질입니다.', '부드러운 계수가 뜨거운 사화 위에 앉아 정재와 정관을 두루 품은 천을귀인의 구조로 두뇌 회전이 대단히 비상합니다. 겉으로는 조용하고 예의 바르지만 속으로는 이해득실을 빠르게 계산하며 환경 적응력이 뛰어나 어디서든 실속을 챙기고 인정받는 외유내강의 표본입니다.', 70, true),
('day_pillar', '계사', 'career', '계사일주 · 직업', '뛰어난 계산 능력과 원만한 대인관계를 살리는 금융, 공직, 외교, 무역 분야에 매우 적합합니다.', '조직 생활에 탁월한 적응력을 보여 대기업이나 공무원 등 반듯한 직장에서 순탄하게 승진 가도를 달립니다. 또한 역마의 기운과 셈이 빠른 재능을 발휘하여 금융권, 회계 혹은 활동적인 유통, 무역, 외교 관련 직무에서도 특유의 정보력을 무기로 큰 성과를 이뤄냅니다.', 70, true),
('day_pillar', '계사', 'love', '계사일주 · 연애', '다정하고 세련된 매너로 상대를 대하며 안정적이고 반듯한 연애와 결혼을 추구합니다.', '배려심이 깊고 낭만적이어서 이성에게 호감을 쉽게 얻으며 관계를 유지하는 데 탁월한 능력을 발휘합니다. 현실적이고 계산적인 면모도 있어 상대방의 조건과 도덕성을 꼼꼼히 살피지만, 일단 인연을 맺으면 가정에 충실하고 예의를 지키는 훌륭한 배우자 감이 됩니다.', 70, true),
('day_pillar', '계사', 'wealth', '계사일주 · 재물', '치밀한 계획과 영리한 수완으로 위험을 피해 가며 안정적이고 큰 재물을 쌓는 성향입니다.', '돈 냄새를 맡는 감각이 뛰어나며 불필요한 지출을 철저히 막아 실속 있게 자산을 굴려 나갑니다. 명예가 높아짐에 따라 자연스레 경제적 보상이 따르는 구조이며, 사업을 하더라도 투기성 짙은 아이템보다는 현금 흐름이 확실한 유통이나 금융 투자를 통해 알부자로 자리 잡습니다.', 70, true),
('day_pillar', '계사', 'health', '계사일주 · 건강', '수와 화의 대비로 심혈관계와 신경성 위장병, 비뇨기 계통의 건강 관리에 신경 쓰면 좋습니다.', '생각이 많고 완벽을 추구하다 보니 스트레스가 누적되어 심장에 열이 차거나 신장 기능이 저하될 우려가 있습니다. 규칙적인 생활 리듬을 지키고 충분한 수분 섭취를 통해 기혈의 순환을 돕는 것이 중요하며, 마음을 편안하게 먹는 정적인 취미를 갖는 것이 이롭습니다.', 70, true),
('day_pillar', '갑오', 'general', '갑오일주 · 총운', '타오르는 장작불처럼 기백이 넘치고 다재다능하며 표현력이 돋보이는 열정적인 기질입니다.', '갑목의 곧은 기상과 오화의 뜨거운 열기가 만나 목생화의 상관 기운을 대단히 강하게 분출하는 형상입니다. 두뇌가 총명하고 언변이 뛰어나며 예술적 감각과 아이디어가 무궁무진하게 샘솟습니다. 남에게 굽히기 싫어하는 반항기도 있지만 불의를 참지 못하는 정의로운 성품입니다.', 70, true),
('day_pillar', '갑오', 'career', '갑오일주 · 직업', '뛰어난 언변과 창의력을 발휘할 수 있는 언론, 방송, 교육, 예술, 기획 분야에 훌륭하게 맞습니다.', '다재다능하고 표현력이 남달라 가르치고 말하는 교육자, 아나운서, 강사 등에서 사람들을 압도하는 능력을 발휘합니다. 자유로운 환경에서 역량이 돋보이므로 엄격한 조직 생활보다는 디자인, 연예, 예술 등 창조성을 발산하는 전문적인 분야에서 크게 성공할 수 있습니다.', 70, true),
('day_pillar', '갑오', 'love', '갑오일주 · 연애', '감정 표현이 솔직하고 열정적이지만 변덕이 심하고 쉽게 불타올랐다 식는 편입니다.', '로맨틱하고 화끈한 분위기로 연애를 주도하며 뛰어난 화술로 상대방의 마음을 금세 사로잡습니다. 하지만 상관의 기운 탓에 상대의 단점이 보이면 날카롭게 지적하거나 구속받는 것을 견디지 못하고 이별을 고할 수 있으니 인내심을 갖고 단점을 포용하는 성숙함이 필요합니다.', 70, true),
('day_pillar', '갑오', 'wealth', '갑오일주 · 재물', '아이디어와 뛰어난 수완으로 재물을 창출하지만 기분파 성향으로 지출도 큰 흐름입니다.', '돈 버는 재주와 수완이 비상하여 재물을 모으는 능력은 탁월하나 재물을 저장하는 창고가 부족해 충동적이거나 과시성 지출로 돈이 흩어지기 쉽습니다. 따라서 번 돈을 현금으로 가지고 있기보다는 부동산, 문서, 자격증 등으로 묶어두는 계획적인 자산 관리가 부를 지키는 비결입니다.', 70, true),
('day_pillar', '갑오', 'health', '갑오일주 · 건강', '에너지 소모가 극심하므로 심혈관 질환과 신경계, 간 기능 보호에 신경 쓰면 좋습니다.', '열기가 넘쳐 감정 기복이 심해지고 활동량이 많아 체력이 금세 고갈되거나 심장에 무리가 올 수 있는 체질입니다. 과로를 피하고 충분한 수면과 명상을 통해 마음의 화기를 다스리며, 간 기능에 부담을 주지 않도록 술과 자극적인 음식을 멀리하는 것이 건강 유지에 필수적입니다.', 70, true),
('day_pillar', '을미', 'general', '을미일주 · 총운', '건조한 대지에 뿌리를 내린 강인한 초목처럼 끈질긴 인내력과 예리한 통찰력을 지녔습니다.', '부드러운 을목이 메마른 미토 위에서 버티는 편재의 구조로, 겉보기엔 수더분하고 다정해 보이지만 내면에는 극한의 환경도 이겨내는 강인한 생명력과 굽히지 않는 고집이 서려 있습니다. 직관이 뛰어나고 셈이 매우 빨라 현실적인 이익을 챙기는 수완이 남다릅니다.', 70, true),
('day_pillar', '을미', 'career', '을미일주 · 직업', '예리한 분석력과 끈기를 요하는 회계, 금융, 부동산, 활인(의료, 상담) 분야에 적합합니다.', '돈 냄새를 맡는 감각이 탁월하여 재무, 세무, 금융업에서 치밀하게 능력을 발휘하며 땅과 인연이 깊어 건축이나 부동산 관련 비즈니스에서도 성과를 잘 냅니다. 또한 예민한 직관을 타인을 돕는 데 쓰는 종교인이나 의료인, 상담사로서도 사회적인 존경과 부를 얻기 좋습니다.', 70, true),
('day_pillar', '을미', 'love', '을미일주 · 연애', '정 많고 다정하나 내면의 외로움이 깊고 감정 기복에 따라 상대에게 예민하게 굴기 쉽습니다.', '연인을 살뜰히 챙기고 따뜻하게 대하지만 목극토의 긴장 상태 탓에 심리적인 압박감을 스스로 만들어내 상대에게 신경질적인 반응을 보일 때가 있습니다. 속마음을 털어놓지 않고 혼자 삭이다가 폭발하는 경향이 있으니 서로 감정을 진솔하게 나누는 소통의 시간이 중요합니다.', 70, true),
('day_pillar', '을미', 'wealth', '을미일주 · 재물', '뛰어난 경제 관념을 바탕으로 근검절약하며 치밀하게 재산을 굴리는 알부자의 성향입니다.', '편재를 깔고 있어 돈을 다루는 스케일과 감각이 매우 발달했으나 무모하게 투기하기보다는 꼼꼼한 계산 아래 철저히 수익을 남깁니다. 마른 흙에 수분이 필요한 형국이므로 무리하게 현금을 회전시키기보다 부동산이나 문서 형태의 실물 자산으로 축적하는 것이 안전하고 유리합니다.', 70, true),
('day_pillar', '을미', 'health', '을미일주 · 건강', '수기가 부족해지기 쉬운 구조이므로 위장병 및 피부, 관절 건강에 유의하고 수분을 보충하면 좋습니다.', '건조하고 뜨거운 흙의 기운으로 인해 위장에 열이 발생하여 소화 장애나 피부 건조증, 변비 등에 시달릴 수 있습니다. 평소 물을 충분히 섭취하고 부드러운 음식을 즐기며, 뭉친 근육과 관절을 유연하게 풀어주는 가벼운 요가나 체조를 생활화하는 것이 건강 관리에 큰 도움이 됩니다.', 70, true),
('day_pillar', '병신', 'general', '병신일주 · 총운', '저녁노을에 비친 화려한 금빛처럼 다재다능하고 사교적이며 두뇌 회전이 매우 빠른 기질입니다.', '병화의 열정적이고 밝은 성향이 신금의 예리한 바위를 녹여내는 편재 역마의 기운으로 스케일이 크고 활동력이 왕성합니다. 사람들과 어울리기를 좋아하고 언변이 뛰어나며 호기심이 많아 다방면에 지식이 풍부합니다. 변화를 두려워하지 않는 개척 정신과 결단력이 돋보입니다.', 70, true),
('day_pillar', '병신', 'career', '병신일주 · 직업', '넓은 무대를 누비는 무역, 유통, 외교, 금융, 기획 및 영업 분야에 훌륭하게 맞습니다.', '역마성의 기운이 강렬하여 한자리에 머무는 일보다는 해외를 넘나들거나 활발하게 움직이는 유통업, 운수업, 무역 등에서 눈부신 성과를 냅니다. 돈의 흐름을 읽는 감각과 기발한 기획력이 있어 금융업이나 대규모 영업 조직에서도 리더로 크게 성공할 수 있는 자질이 충분합니다.', 70, true),
('day_pillar', '병신', 'love', '병신일주 · 연애', '매너 좋고 유쾌하여 이성에게 인기가 높으나 쉽게 싫증을 내거나 마음이 흩어지기 쉽습니다.', '화려한 언변과 로맨틱한 분위기로 상대를 매혹하며 연애를 주도하는 매력이 철철 넘칩니다. 그러나 감정 기복이 있고 구속받는 것을 극도로 싫어하는 자유로운 성향 탓에 관계가 불안정해질 수 있으므로 한 사람에게 진지하게 헌신하고 신뢰를 쌓아가는 책임감이 몹시 요구됩니다.', 70, true),
('day_pillar', '병신', 'wealth', '병신일주 · 재물', '뛰어난 정보력과 활동성을 무기로 큰 재물을 단숨에 벌어들이는 통 큰 사업가의 흐름입니다.', '재물의 스케일이 커서 월급보다는 자신의 뛰어난 수완과 사업적인 감각으로 굵직한 수익을 올리는 데 재능이 탁월합니다. 다만 편재 특유의 투기성이나 잦은 변화로 인해 재산이 흩어질 위험이 도사리므로, 굴린 현금을 즉시 안정적인 부동산 문서로 전환하는 재테크 지혜가 필수입니다.', 70, true),
('day_pillar', '병신', 'health', '병신일주 · 건강', '활동성이 강해 심혈관계와 신경계에 무리가 갈 수 있으니 호흡기 건강 관리에 신경 쓰면 좋습니다.', '에너지를 외부로 한껏 발산하다 보니 쉽게 피로가 누적되고 신경이 날카로워져 불면증이나 심장 떨림을 겪을 우려가 있습니다. 화극금의 영향으로 호흡기나 대장 기능이 예민해질 수 있으니 규칙적인 휴식을 엄수하고 맑은 공기를 쐬며 폐를 보호하는 유산소 운동이 바람직합니다.', 70, true),
('day_pillar', '정유', 'general', '정유일주 · 총운', '어둠을 밝히는 등불 앞의 보석처럼 정교하고 미적 감각이 탁월하며 세밀한 기질입니다.', '은은한 정화가 유금이라는 깔끔하고 예리한 보석을 비추는 편재의 구조로 대단히 섬세하고 직관력이 비상합니다. 겉보기엔 부드럽고 세련되었으며 남을 배려하는 성품이지만 내면에는 정확한 계산과 높은 이상을 품고 있어 맺고 끊음이 차갑고 명확한 완벽주의 성향을 띱니다.', 70, true),
('day_pillar', '정유', 'career', '정유일주 · 직업', '세밀한 손재주와 감각을 요하는 금융, 디자인, 예술, 정밀 기술, 기획 분야에 적합합니다.', '금전을 치밀하게 다루는 회계사나 세무사 등에서 특유의 날카로움을 십분 발휘하며, 뛰어난 미적 감각으로 미용, 패션, 인테리어 디자인 분야에서도 독보적인 역량을 뽐냅니다. 사람을 끌어당기는 천을귀인의 매력이 있어 기획이나 서비스업에서도 많은 이들의 인정과 지지를 받습니다.', 70, true),
('day_pillar', '정유', 'love', '정유일주 · 연애', '다정하고 낭만적으로 상대를 대하지만 마음속 잣대가 높아 까다롭고 예민한 편입니다.', '세련된 매력과 다정다감한 성격으로 인기가 많으나 상대방의 작은 실수나 결점에도 쉽게 마음이 식거나 날카롭게 지적하는 차가운 면모가 숨어 있습니다. 지나치게 결백하거나 완벽을 요구하면 관계가 피곤해지므로 상대의 부족함을 따뜻하게 감싸안는 너그러움이 필요합니다.', 70, true),
('day_pillar', '정유', 'wealth', '정유일주 · 재물', '정밀한 분석과 남다른 재물 감각을 바탕으로 알뜰하게 큰 부를 축적하는 성향입니다.', '천을귀인의 재물복을 깔고 있어 평생 경제적인 궁핍함이 적으며 돈을 다루는 솜씨가 매우 치밀합니다. 무모한 횡재를 노리기보다 자신의 예리한 기술과 직관을 살려 안정적인 수익 모델을 구축하고 불필요한 낭비를 철저히 막아 중년 이후 상당한 부자로 거듭나는 유리한 흐름입니다.', 70, true),
('day_pillar', '정유', 'health', '정유일주 · 건강', '화극금의 대립으로 호흡기 및 대장 기능이 예민해지기 쉬운 체질이니 시력과 신경 관리에 유의하면 좋습니다.', '스트레스를 받으면 폐나 기관지가 약해지고 장이 예민해져 소화 장애가 생길 수 있으니 평소 수분을 자주 보충해야 합니다. 신경이 예민해 불면증이나 편두통, 안구 건조증 등에 시달릴 수 있으므로 눈의 피로를 풀어주고 따뜻한 차나 명상으로 마음을 편안하게 이완시키는 것이 중요합니다.', 70, true),
('day_pillar', '무술', 'general', '무술일주 · 총운', '가을 산맥처럼 장엄하고 고집이 강하며, 신의와 뚝심으로 밀어붙이는 호탕한 기질입니다.', '무토와 술토가 만난 간여지동의 괴강살 기운으로 타의 추종을 불허하는 주관과 극강의 독립심을 자랑합니다. 겉보기엔 무뚝뚝하고 감정 표현이 서툴러 보이지만 내면은 불(火)처럼 뜨거운 열정과 깊은 의리를 품고 있으며 한 번 믿음을 준 사람에게는 목숨을 걸 만큼 헌신적입니다.', 70, true),
('day_pillar', '무술', 'career', '무술일주 · 직업', '강한 주도권과 전문성을 요하는 군검경, 정치, 부동산, 활인(상담, 종교) 분야에 잘 맞습니다.', '누군가의 지시를 받기보다는 거대한 프로젝트를 독자적으로 이끌어가는 정치, 토목, 건축 분야에서 탁월한 통솔력을 보여줍니다. 남을 통제하는 수사기관이나 반대로 사람의 마음을 치유하고 이끄는 종교, 철학, 심리 상담 등의 특수 분야에서도 사회적으로 크게 성공할 잠재력이 풍부합니다.', 70, true),
('day_pillar', '무술', 'love', '무술일주 · 연애', '책임감 있게 상대를 보호하나 무뚝뚝함과 굽히지 않는 자존심 탓에 갈등이 잦을 수 있습니다.', '가벼운 연애를 멀리하고 듬직하게 배우자를 챙기려는 성향이지만 고집이 워낙 세어 상대방이 답답함이나 억압을 느낄 위험이 큽니다. 표현 방식이 서툴러 오해를 사기 쉬우니 한 발짝 물러서서 상대의 감정에 귀 기울이고 부드러운 애정 표현을 습관화하려는 노력이 관계 유지에 필수입니다.', 70, true),
('day_pillar', '무술', 'wealth', '무술일주 · 재물', '안정적인 부동산이나 문서 자산을 통해 묵직하게 스케일이 큰 부를 쌓아가는 성향입니다.', '현금 흐름을 좇는 유행성 사업보다는 땅이나 건물 등 변치 않는 실물 자산에 투자할 때 잠재된 엄청난 재물복이 발현됩니다. 돈을 흩뿌리기보다는 흙 속에 묻어두듯 철저히 묶어두는 능력이 뛰어나며 한 번 크게 재물을 쥐면 쉽게 놓치지 않고 든든한 재력을 유지하는 구조입니다.', 70, true),
('day_pillar', '무술', 'health', '무술일주 · 건강', '수기가 마르고 화기가 강해지기 쉬우니 위장 및 간, 신장 기능 관리에 유의하면 좋습니다.', '건조한 기운 탓에 위장에 열이 뭉쳐 소화 장애나 변비, 피부 건조증 등에 취약하므로 수분 대사를 원활하게 하는 것이 중요합니다. 화를 겉으로 폭발하거나 안으로 심하게 삭여 간에 무리가 가지 않도록 스트레스를 건전한 야외 운동이나 등산 등으로 시원하게 발산하는 것이 건강에 이롭습니다.', 70, true),
('day_pillar', '기해', 'general', '기해일주 · 총운', '물가에 펼쳐진 비옥한 들판처럼 포용력이 넓고 융통성이 뛰어나며 예민한 직관을 지녔습니다.', '부드러운 기토 아래에 차가운 해수가 흐르는 정재의 구조로 겉모습은 몹시 수더분하고 다정다감하여 대인관계가 원만합니다. 하지만 내면에는 기민한 눈치와 치밀한 계산 능력이 숨어 있어 환경 변화에 민첩하게 적응하며 보이지 않는 곳에서 실속을 철저히 챙기는 영리함을 갖췄습니다.', 70, true),
('day_pillar', '기해', 'career', '기해일주 · 직업', '치밀한 계산과 융통성을 발휘하는 재무, 기획, 무역, 교육, 정보통신 분야에 적합합니다.', '돈을 관리하고 굴리는 감각이 뛰어나 회계사나 금융업 종사자로서 탁월한 능률을 자랑합니다. 천문성의 영향으로 사람의 심리를 꿰뚫어보는 기획이나 상담, 교육 분야에 강하며, 물 위를 떠도는 역마의 특성을 살려 해운업이나 무역, 외교 관련 직무에서도 크게 역량을 펼칠 수 있습니다.', 70, true),
('day_pillar', '기해', 'love', '기해일주 · 연애', '부드럽고 낭만적으로 헌신하지만 마음속으로 상대를 꼼꼼히 평가하는 신중함이 있습니다.', '연인에게 따뜻한 배려와 헌신을 아끼지 않아 안정적인 관계를 이끌어갑니다. 속마음을 잘 드러내지 않으면서도 의심이나 불안감이 피어오르면 혼자서 예민하게 앓는 경향이 있으니, 상대방을 섣불리 의심하기보다 열린 마음으로 진솔한 대화를 나누며 신뢰를 탄탄히 다지는 것이 중요합니다.', 70, true),
('day_pillar', '기해', 'wealth', '기해일주 · 재물', '알뜰한 절약 정신과 치밀한 계획으로 낭비 없이 꼼꼼하게 알부자가 되는 성향입니다.', '재물의 흐름을 정확히 꿰뚫어보는 정재 특유의 감각으로 헛돈을 쓰지 않고 차곡차곡 재산을 쌓아 올립니다. 무리한 사업 확장이나 횡재를 바라기보다 안정적인 월급이나 이자, 임대 수익 등 예측 가능한 재테크를 통해 경제적 독립을 굳건히 이루어 내는 대단히 실속파적인 흐름입니다.', 70, true),
('day_pillar', '기해', 'health', '기해일주 · 건강', '냉기가 스며들기 쉬운 구조이므로 비위장 건강과 하복부 보온에 유의하면 좋습니다.', '차가운 물이 흙을 차갑게 만들어 소화기 계통이 약해지거나 위장병에 시달릴 수 있으니 찬 음식을 피하고 부드럽고 따뜻한 식단을 유지해야 합니다. 하체가 차가워져 신경통이나 비뇨기 질환이 올 수 있으므로 족욕이나 반신욕 등으로 체온을 높이고 혈액순환을 돕는 습관이 건강의 비결입니다.', 70, true),
('day_pillar', '경자', 'general', '경자일주 · 총운', '맑고 차가운 금속에서 물이 샘솟듯 두뇌가 비상하고 예리하며 표현력이 출중한 기질입니다.', '단단한 경금이 지혜의 상징인 자수 상관을 만나 겉으로는 이지적이고 깔끔해 보이나 내면에는 굽히지 않는 차가운 칼날 같은 비판력과 승부욕을 지녔습니다. 다재다능하고 예술적 감수성이 뛰어나며 불합리한 것을 참지 못해 직언을 서슴지 않는 날카로운 매력을 발산합니다.', 70, true),
('day_pillar', '경자', 'career', '경자일주 · 직업', '비상한 두뇌와 뛰어난 화술을 요하는 교육, 연구, 언론, 예술, 기획 분야에 훌륭하게 맞습니다.', '금생수의 맑은 기운으로 직관력과 분석력이 압도적이라 학자, 연구원, 데이터 분석가 등에서 최고의 성과를 냅니다. 상관의 화려한 표현력을 바탕으로 남을 가르치는 교육자, 기자, 평론가 혹은 창의적인 예술가로서 대중의 시선을 사로잡으며 독립적인 환경에서 능률이 치솟습니다.', 70, true),
('day_pillar', '경자', 'love', '경자일주 · 연애', '세련된 매력과 다정함으로 호감을 사나 눈높이가 높고 상대의 결점에 대단히 예민합니다.', '이성에게 인기가 많고 섬세한 애정 표현으로 낭만적인 관계를 리드하지만 자존심이 세고 비판적인 성향이 짙어 다툼이 생길 때 상대에게 깊은 상처를 줄 수 있습니다. 타인을 가르치고 통제하려는 태도를 내려놓고 너그러운 이해심으로 다름을 수용하는 훈련이 원만한 연애를 위해 필수적입니다.', 70, true),
('day_pillar', '경자', 'wealth', '경자일주 · 재물', '뛰어난 아이디어와 전문적인 지식, 자격을 활용하여 안정적인 수익을 창출하는 흐름입니다.', '남다른 기획력과 창의적인 재능을 현금으로 연결하는 수완이 대단히 탁월합니다. 다만 자기 과시나 기분파적인 지출 탓에 재물이 쉽게 흩어질 위험이 존재하므로 수익을 투기성 사업에 재투자하기보다는 자격증, 저작권, 혹은 확실한 문서 형태로 단단히 묶어두는 것이 재산을 지키는 안전판입니다.', 70, true),
('day_pillar', '경자', 'health', '경자일주 · 건강', '금수 기운이 차가우므로 하복부를 덥히고 호흡기 및 심혈관 건강 관리에 유의하면 좋습니다.', '물이 지나치게 차가워져 기혈의 순환이 정체되기 쉽고 신장이나 생식기 계통이 약해질 우려가 큽니다. 스트레스가 심해지면 신경성 두통이나 폐 기능 저하로 이어질 수 있으니 무리한 활동을 줄이고 따뜻한 차와 땀을 내는 가벼운 유산소 운동으로 신체의 냉기를 몰아내는 것이 바람직합니다.', 70, true),
('day_pillar', '신축', 'general', '신축일주 · 총운', '꽁꽁 언 땅속에 묻힌 보석처럼 차분하고 인내심이 깊으며 날카로운 직관을 지닌 기질입니다.', '신금의 날카롭고 섬세한 기운이 축토의 묵묵한 인내력과 만나 겉보기엔 매우 수더분하고 과묵해 보입니다. 하지만 내면에는 편인의 깊은 사유와 비상한 두뇌 회전, 그리고 자신이 목표한 바를 끝내 이루고야 마는 대단한 고집과 결단력이 서려 있는 외유내강의 전형입니다.', 70, true),
('day_pillar', '신축', 'career', '신축일주 · 직업', '정밀함과 특수한 전문 지식을 요하는 의료, 회계, 종교, 기획 및 첨단 기술 분야에 적합합니다.', '냉철한 판단력과 뛰어난 손재주를 발휘할 수 있는 치과의사, 한의사, 세무사 등 정밀한 면허를 요구하는 직무에서 눈부신 성취를 냅니다. 남들이 쉽게 파악하지 못하는 이면을 읽어내는 능력이 있어 심리 상담이나 종교, 명리학 분야, 혹은 데이터 분석 기획에서 확고한 전문성을 다집니다.', 70, true),
('day_pillar', '신축', 'love', '신축일주 · 연애', '신중하게 곁을 내어주며 한 번 맺은 인연에 깊이 헌신하나 내면의 고집이 대단히 강합니다.', '상대방을 오랜 시간 관찰한 뒤에야 마음을 여는 까다로움이 있으며 표현이 서툴러 다소 차갑게 느껴질 수 있습니다. 연인에게 속마음을 잘 드러내지 않아 오해를 사기 쉬우며 자기만의 굳건한 잣대로 상대를 평가하려 들기 쉬우니 긍정적인 대화로 감정을 솔직하게 나누려는 연습이 중요합니다.', 70, true),
('day_pillar', '신축', 'wealth', '신축일주 · 재물', '근검절약과 치밀한 재무 관리를 바탕으로 실물 자산과 문서를 통해 부를 거머쥐는 성향입니다.', '돈을 허투루 쓰지 않는 철저한 절약 정신과 보수적인 투자 성향으로 남몰래 상당한 재산을 묵직하게 쌓아 올립니다. 위험 부담이 큰 사업이나 주식보다는 흙 속에 보석을 묻어두듯 부동산, 건물, 특수 자격증을 통해 알짜배기로 자산을 불려가는 것이 훗날 큰 부를 누리는 든든한 흐름입니다.', 70, true),
('day_pillar', '신축', 'health', '신축일주 · 건강', '몸이 대단히 차가워지기 쉬운 구조이므로 비위장 건강과 호흡기 보온에 유의하면 좋습니다.', '금과 습한 흙이 만나 체온이 떨어지고 소화 기능이 극도로 예민해져 위염이나 장 트러블에 시달리기 쉽습니다. 따뜻한 성질의 음식을 섭취하고 배를 항상 따뜻하게 덥혀주는 것이 좋으며 뭉친 신경과 근육을 풀어주기 위해 스트레칭이나 온욕을 자주 즐기는 습관이 건강 유지에 큰 보탬이 됩니다.', 70, true),
('day_pillar', '임인', 'general', '임인일주 · 총운', '너른 강물 위를 뛰노는 호랑이처럼 재치가 넘치고 활동적이며 낙천적인 기질입니다.', '포용력 넓은 임수가 생동감 넘치는 인목을 만나 수생목의 식신 기운을 활발하게 분출하는 형상입니다. 사람들을 아우르는 다정함과 화려한 언변을 갖췄으며 두뇌 회전이 대단히 빨라 어떠한 환경에서도 기발한 아이디어와 기민한 대처 능력으로 위기를 기회로 바꾸는 호탕한 성향을 띱니다.', 70, true),
('day_pillar', '임인', 'career', '임인일주 · 직업', '창의력과 활동력을 발휘하는 무역, 교육, 기획, 언론, 유통 등 역동적인 분야에 잘 맞습니다.', '뛰어난 설득력과 아이디어를 무기로 교육자나 기획자, 마케팅 전문가로서 사람들의 마음을 사로잡고 이끄는 데 능숙합니다. 문창귀인의 영리함과 역마의 활동성이 더해져 글로벌 무대에서 활약하는 무역, 외교, 유통업에서 큰 스케일로 독자적인 비즈니스를 개척하며 두각을 나타냅니다.', 70, true),
('day_pillar', '임인', 'love', '임인일주 · 연애', '유쾌하고 다정다감한 태도로 인기가 많으나 자유를 억압받는 것을 극도로 싫어합니다.', '센스 있고 로맨틱한 데이트를 주도하며 뛰어난 화술로 연인의 마음을 즐겁게 해주는 능력이 탁월합니다. 그러나 특유의 호기심과 구속을 싫어하는 방랑자적 기질 탓에 한 사람에게 온전히 정착하기까지 시간이 걸릴 수 있으므로 책임감을 가지고 상대에게 진지한 신뢰를 보여주는 것이 중요합니다.', 70, true),
('day_pillar', '임인', 'wealth', '임인일주 · 재물', '탁월한 정보력과 번뜩이는 재치로 쉴 새 없이 수익을 창출해 내는 능력 있는 흐름입니다.', '식신생재의 원활한 흐름을 타므로 평생 먹을 복과 재물복이 마르지 않으며 남들이 보지 못하는 틈새시장을 노려 큰 돈을 벌어들입니다. 다만 활동 반경이 넓고 기분파적인 지출이 잦아 재산이 쉽게 흩어질 우려가 크니 벌어들인 재물을 안정적인 부동산이나 문서로 단단히 묶어두는 관리가 필수적입니다.', 70, true),
('day_pillar', '임인', 'health', '임인일주 · 건강', '과도한 에너지 소모로 신경성 질환이나 심장, 간 기능에 무리가 갈 수 있으니 유의하면 좋습니다.', '끊임없이 머리를 쓰고 바쁘게 움직이는 탓에 간 피로도가 높아지고 수면 부족이나 신경 쇠약을 겪기 쉬운 체질입니다. 과로와 잦은 술자리를 멀리하고 충분한 수면으로 뇌의 피로를 풀어주며 요가나 명상처럼 몸과 마음의 속도를 늦출 수 있는 이완 활동을 일상화하는 것이 건강에 매우 유익합니다.', 70, true),
('day_pillar', '계묘', 'general', '계묘일주 · 총운', '봄비에 젖은 화초처럼 맑고 다정다감하며 뛰어난 감수성과 예술적 감각을 지닌 기질입니다.', '섬세한 계수가 부드럽고 여린 묘목 식신에 생명력을 불어넣는 구조로 겉보기엔 대단히 순수하고 사람들에게 상냥한 호감을 줍니다. 뛰어난 직관력과 천을귀인의 보호를 받아 위기 속에서도 귀인의 도움을 얻는 복을 타고났으며 주변과 마찰을 피하고 평화롭게 조화를 이루려는 성향이 돋보입니다.', 70, true),
('day_pillar', '계묘', 'career', '계묘일주 · 직업', '섬세한 감각과 사람을 대하는 교육, 예술, 기획, 의료, 상담 분야에 훌륭하게 맞습니다.', '남의 마음을 부드럽게 헤아리고 양육하는 능력이 출중해 교육자, 상담사, 간호사 등 활인업에서 사회적 존경과 안정을 거머쥡니다. 창의력과 미적 감각이 매우 예리하여 디자인, 패션, 문학, 요식업 분야에서도 자신만의 세련된 결과물로 대중적인 인기와 성공을 끌어낼 수 있는 자질이 충분합니다.', 70, true),
('day_pillar', '계묘', 'love', '계묘일주 · 연애', '낭만적이고 헌신적으로 사랑을 베푸나 감정 기복이 예민하여 상처에 취약한 편입니다.', '선하고 부드러운 매너로 이성에게 인기가 높으며 연인에게 세심한 배려를 아끼지 않아 따뜻한 관계를 유지합니다. 하지만 겉으로 보이는 유순함 속에 여린 감수성이 자리해 사소한 말 한마디에도 쉽게 상처받고 혼자 우울감에 빠질 수 있으므로 믿음직하고 심리적인 안정감을 주는 동반자가 필수적입니다.', 70, true),
('day_pillar', '계묘', 'wealth', '계묘일주 · 재물', '안정적인 전문 지식과 뛰어난 손재주를 발휘해 알뜰하게 부를 축적하는 실속파의 성향입니다.', '식신의 길한 기운과 천을귀인을 두루 갖춰 일생 동안 경제적인 어려움에서 쉽게 벗어나는 넉넉한 재물복을 타고났습니다. 투기적인 욕심이나 큰 횡재를 노리기보다 자신의 독보적인 아이디어나 전문 자격증, 학위 등을 바탕으로 꼼꼼하게 실속을 챙기며 점진적으로 부를 불려가는 평탄한 흐름에 능합니다.', 70, true),
('day_pillar', '계묘', 'health', '계묘일주 · 건강', '신경이 예민해지기 쉬우므로 심리적 안정이 필요하고 위장 및 비뇨기 계통에 유의하면 좋습니다.', '생각이 많고 여린 성격 탓에 스트레스를 내면으로 삭이다 불면증이나 신경성 위장 장애에 쉽게 시달릴 수 있습니다. 몸이 다소 차가워질 수 있는 기운이므로 차가운 음식을 피하고 아랫배를 따뜻하게 보온하며 긴장을 부드럽게 이완시키는 걷기 명상이나 다도 등을 즐기는 것이 훌륭한 건강 관리법입니다.', 70, true)
